import ast
import json
from typing import List, Optional

import requests
from langchain import PromptTemplate
from langchain.schema import Document

from config.settings import environment
from engine import CustomComponent
from engine.interface.utils import json_prompt_format


class BrcModelProxyVision(CustomComponent):
    display_name: str = "多图视觉对话"
    description: str = "调用多模态接口，支持多张图片输入"
    beta = False

    field_config = {
        "api_url": {
            "display_name": "接口地址",
            "info": "默认测试地址，可按环境覆盖",
        },
        "authorization": {
            "display_name": "Authorization",
            "info": "Bearer Token，支持直接填 token 或 Bearer xxx",
        },
        "model_name": {
            "display_name": "模型名称",
            "info": "例如 qwen-vl-post",
        },
        "caller": {"display_name": "caller"},
        "channel_application_name": {"display_name": "channelApplicationName"},
        "create_user": {"display_name": "createUser"},
        "temperature": {"display_name": "温度"},
        "max_tokens": {"display_name": "最大输出Token"},
        "system_prompt": {"display_name": "系统提示词"},
        "user_prompt": {"display_name": "用户提示词"},
        "store_img": {
            "display_name": "门店图",
            "info": "单个URL",
        },
        "sku_imgs": {
            "display_name": "SKU图片",
            "info": "支持单个URL、JSON数组或多路输入",
        },
        "is_sdk": {"display_name": "isSdk"},
        "timeout": {"display_name": "超时时间(秒)"},
        "code": {"show": True},
    }

    @staticmethod
    def _normalize_auth(authorization: str) -> str:
        token = (authorization or "").strip()
        if not token:
            return ""
        if token.lower().startswith("bearer "):
            return token
        return f"Bearer {token}"

    @staticmethod
    def _parse_values(value: Optional[str]) -> List[str]:
        if value is None:
            return []
        if not isinstance(value, str):
            return [str(value)]

        text = value.strip()
        if not text:
            return []

        for parser in (json.loads, ast.literal_eval):
            try:
                parsed = parser(text)
                if isinstance(parsed, list):
                    return [str(item).strip() for item in parsed if str(item).strip()]
            except Exception:
                pass
        return [text]

    def _parse_store_img(self, store_img: Optional[Document]) -> List[str]:
        if not store_img:
            return []
        return self._parse_values(store_img.page_content)

    def _parse_sku_imgs(self, sku_imgs: Optional[List[Document]]) -> List[str]:
        image_urls: List[str] = []
        for image_doc in sku_imgs or []:
            image_urls.extend(self._parse_values(image_doc.page_content))
        return image_urls

    @staticmethod
    def _extract_content(response_json: dict) -> str:
        if isinstance(response_json, dict):
            if "content" in response_json:
                return str(response_json["content"][0])
            choices = response_json.get("choices", [])
            if choices and isinstance(choices, list):
                message = choices[0].get("message", {})
                if isinstance(message, dict) and "content" in message:
                    return str(message["content"][0])
        return json.dumps(response_json, ensure_ascii=False)

    def build(
        self,
        store_img: Optional[Document] = None,
        sku_imgs: Optional[List[Document]] = None,
        system_prompt: Optional[PromptTemplate] = None,
        user_prompt: Optional[PromptTemplate] = None,
        authorization: str = "",
        api_url: str = "https://aism.mengniu.cn/brcapi/model-proxy-service/api/internal/v1/chat/completions",
        model_name: str = "qwen-vl-post",
        caller: str = "测试",
        channel_application_name: str = "测试",
        create_user: str = "测试",
        temperature: str = "0.0",
        max_tokens: str = "2048",
        is_sdk: bool = True,
        timeout: int = 300,
    ) -> Document:
        store_urls = self._parse_store_img(store_img)
        sku_urls = self._parse_sku_imgs(sku_imgs)

        if not store_urls:
            raise ValueError("store_img 不能为空，至少传入一张门店图URL。")
        if not sku_urls:
            raise ValueError("sku_imgs 不能为空，至少传入一张SKU图URL。")

        image_urls = store_urls + sku_urls

        system_text = json_prompt_format(system_prompt) if system_prompt else ""
        user_text = json_prompt_format(user_prompt) if user_prompt else "请基于图片完成分析。"

        user_content = []
        for idx, image_url in enumerate(image_urls):
            item = {
                "type": "image_url",
                "image_url": {"url": image_url}
            }
            user_content.append(item)

        user_content.append({"type": "text", "text": user_text})

        payload = {
            "caller": caller,
            "channelApplicationName": channel_application_name,
            "createUser": create_user,
            "temperature": float(temperature),
            "top_p": 0.1,
            "top_k": 1,
            "seed": 42,
            "messages": [
                {"role": "system", "content": system_text},
                {"role": "user", "content": user_content},
            ],
            "isSdk": is_sdk,
            "max_tokens": int(max_tokens),
            "modelName": model_name,
        }

        headers = {"content-type": "application/json;charset=UTF-8"}
        auth_header = self._normalize_auth(authorization)
        if auth_header:
            headers["authorization"] = auth_header

        response = requests.post(api_url, headers=headers, json=payload, timeout=timeout)
        response.raise_for_status()
        result = self._extract_content(response.json())

        self.repr_value = result
        return Document(page_content=result)

